// Provide a concrete implementation of the abstract SentenceIterator.
class _FuzzTestIterator final : public sentencepiece::SentenceIterator {
 public:
  explicit _FuzzTestIterator(std::vector<std::string> &&data)
      : data_(std::move(data)) {}
  virtual ~_FuzzTestIterator() {}

  bool done() const override { return index_ >= data_.size(); }
  void Next() override { if (!done()) ++index_; }
  const std::string &value() const override {
    if (!done()) return data_[index_];
    // Return a stable empty string reference if called when done (defensive).
    static const std::string kEmpty;
    return kEmpty;
  }
  sentencepiece::util::Status status() const override {
    // Always OK in this simple iterator; training code should check after completion.
    return sentencepiece::util::Status();
  }

 private:
  std::vector<std::string> data_;
  size_t index_ = 0;
};

